            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in foreground and p not in labels:
                    labels[p] = n
                    q.append(p)

    parent = list(range(n + 1))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def join(a, b):
